#include <filesystem>
#include <set>
#include <glm/geometric.hpp>
#include "mpp/SceneDocument.h"
using namespace std;
namespace mpp { DiagnosticBag SceneDocument::validate() const { DiagnosticBag d; if(version!=CurrentVersion)d.error("MPP-SCENE-001","Unsupported Scene version.",{sourcePath}); if(name.empty())d.error("MPP-SCENE-002","Scene name is required.",{sourcePath}); set<string> ids; for(auto const&m:models){if(m.id.empty()||!ids.insert(m.id).second)d.error("MPP-SCENE-003","Model IDs must be non-empty and unique.",{sourcePath},m.id); if(m.source==SceneModelSource::MppModel&&m.file.empty())d.error("MPP-SCENE-004","MPP model file is required.",{sourcePath},m.id);else if(m.source==SceneModelSource::MppModel){auto path=std::filesystem::path(m.file);if(path.is_absolute())d.warning("MPP-SCENE-009","Absolute model path is not portable.",{sourcePath},m.id);auto resolved=path.is_absolute()?path:std::filesystem::path(sourcePath).parent_path()/path;if(!std::filesystem::exists(resolved))d.error("MPP-SCENE-010","Model file does not exist: "+resolved.string(),{sourcePath},m.id);}for(auto const&layer:m.layers)if(layer.empty())d.error("MPP-SCENE-011","Layer names cannot be empty.",{sourcePath},m.id); if(m.materialBinding.empty())d.warning("MPP-SCENE-005","Model has no logical material binding.",{sourcePath},m.id);} for(auto const&l:lights){if(l.id.empty()||!ids.insert(l.id).second)d.error("MPP-SCENE-006","Light IDs must be non-empty and unique.",{sourcePath},l.id);if(l.intensity<0||l.range<0)d.error("MPP-SCENE-012","Light intensity and range cannot be negative.",{sourcePath},l.id);if(l.type==SceneLightType::Directional&&glm::dot(l.direction,l.direction)<0.000001f)d.error("MPP-SCENE-013","Directional light direction cannot be zero.",{sourcePath},l.id);}if(lights.size()>8)d.error("MPP-SCENE-014","Scene exceeds the renderer limit of eight PBR lights.",{sourcePath},"lights"); if(camera.nearPlane<=0||camera.farPlane<=camera.nearPlane)d.error("MPP-SCENE-007","Camera clip distances are invalid.",{sourcePath},"camera"); if(environmentBinding.empty())d.warning("MPP-SCENE-008","Scene has no logical environment binding.",{sourcePath},"environment"); return d; } }
